const ASSETS={"/index.html":{"type":"text/html; charset=utf-8","base64":""},"/app.js":{"type":"application/javascript; charset=utf-8","base64":""},"/local-store.js":{"type":"application/javascript; charset=utf-8","base64":""},"/growth.js":{"type":"application/javascript; charset=utf-8","base64":""},"/growth.css":{"type":"text/css; charset=utf-8","base64":""},"/release-state.js":{"type":"application/javascript; charset=utf-8","base64":""},"/release.json":{"type":"application/json; charset=utf-8","base64":"eyJ2ZXJzaW9uIjoiMy4xLjAiLCJub3RlcyI6IuWutuaXj+mZkOWumuOBruiqjeiovOS7mOOBjemFjeS/oeOBq+WvvuW/nOOAguODreOCsOOCpOODs+acn+mZkOWIh+OCjOOBp+OBruiqpOS/neWtmOOCkumYsuOBjuOBvuOBmeOAguiomOmMsuOBr+W8leOBjee2muOBjWlQYWTlhoXjgaDjgZHjgavkv53lrZjjgZfjgb7jgZnjgIIifQo="},"/update.js":{"type":"application/javascript; charset=utf-8","base64":""},"/sw.js":{"type":"application/javascript; charset=utf-8","base64":""},"/manifest.webmanifest":{"type":"application/manifest+json","base64":""},"/icon-192.png":{"type":"image/png","base64":""},"/icon-512.png":{"type":"image/png","base64":""}};
/* No Static Assets router: ctx.access must be the platform-authenticated context.
   Never trust a user-supplied email header. No database or record APIs exist. */
export default {async fetch(request,env,ctx){
 const deny=(text,status)=>new Response(text,{status,headers:{'Cache-Control':'private, no-store','Content-Type':'text/plain; charset=utf-8','X-Content-Type-Options':'nosniff'}});
 if(!ctx?.access)return deny('家族限定配信の認証設定が必要です。',403);
 let allowed;try{allowed=JSON.parse(env.FAMILY_EMAILS||'[]')}catch{return deny('家族の許可設定を確認してください。',403)}
 if(!Array.isArray(allowed)||!allowed.length||allowed.some(e=>typeof e!=='string'))return deny('家族の許可設定が必要です。',403);
 let identity;try{identity=await ctx.access.getIdentity()}catch{return deny('認証を確認できませんでした。ログインし直してください。',403)}
 const email=identity?.email?.trim().toLowerCase();
 if(!email||!allowed.some(e=>e.trim().toLowerCase()===email))return deny('このアプリは許可された家族専用です。',403);
 if(!['GET','HEAD'].includes(request.method))return deny('この配信先は記録を受け付けません。',405);
 const url=new URL(request.url);
 if(url.pathname==='/family-login')return new Response(null,{status:302,headers:{Location:'/', 'Cache-Control':'private, no-store'}});
 const path=url.pathname==='/'?'/index.html':url.pathname,asset=ASSETS[path];
 if(!asset)return deny('ページが見つかりません。',404);
 const bytes=Uint8Array.from(atob(asset.base64),c=>c.charCodeAt(0));
 return new Response(request.method==='HEAD'?null:bytes,{headers:{
 'Content-Type':asset.type,'Cache-Control':'private, no-store','X-Content-Type-Options':'nosniff','Referrer-Policy':'no-referrer',
 'Content-Security-Policy':"default-src 'self'; script-src 'self'; worker-src 'self'; style-src 'self' 'unsafe-inline'; img-src 'self' data:; connect-src 'self'; object-src 'none'; base-uri 'none'; form-action 'none'; frame-ancestors 'none'",
 'Permissions-Policy':'camera=(), microphone=(), geolocation=(), payment=()',
 ...(path==='/sw.js'?{'Service-Worker-Allowed':'/'}:{})
 }});
}};
